import{_ as o,l as s,o as a,c as n,v as t,p as h,x as i,d as l,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"异方差与 HAC","description":"","frontmatter":{"title":"异方差与 HAC","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hac-heteroskedasticity.md","filePath":"econ/hac-heteroskedasticity.md","lastUpdated":1789023840000}'),d={name:"econ/hac-heteroskedasticity.md"};function m(A,e,p,u,_,B){const r=s("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="异方差与-hac" tabindex="-1">异方差与 HAC <a class="header-anchor" href="#异方差与-hac" aria-label="Permalink to &quot;异方差与 HAC&quot;">​</a></h1><div class="epigraph"><p>系数可以仍一致，默认标准误却按球形误差去算——显著性就被吹大或压扁。White 与 Newey–West 改的是协方差，不是把 OLS 改写成因果。</p><footer>—— White, A Heteroskedasticity-Consistent Covariance Matrix Estimator, Econometrica 1980；Newey and West, Econometrica 1987；对照 Wooldridge, Econometric Analysis of Cross Section and Panel Data</footer></div><p><a href="/econ/ols-gauss-markov">上一课</a>在 \\(\\mathbb{E}[u\\mid X]=0\\) 且 \\(\\mathrm{Var}(u\\mid X)=\\sigma^2 I\\) 下给出 BLUE。本课不重推正规方程，也不把 Gauss–Markov 再证一遍。缺口只在第二句：球形一破，OLS 仍可无偏一致，但 \\(s^2(X&#39;X)^{-1}\\) 不再是 \\(\\mathrm{Var}(\\hat\\beta)\\)。后课<a href="/econ/clustered-se">聚类标准误</a>把相关从「一条时间序列」扩到「一组之内」；本课先钉截面异方差与单方程 HAC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工资对教育、消费对收入：高 \\(X\\) 处残差往往更散。宏观月度：\\(u_t\\) 带着记忆，相邻期不是独立。两种破坏都让默认 \\(t\\) 的名义水平说谎。缺口不是换点估计——外生仍在时 \\(\\hat\\beta\\) 对准线性 CEF——而是三明治中间那一块 \\(\\mathbb{E}[uu&#39;]\\) 不能再写成 \\(\\sigma^2 I\\)。用错 SE，政策表上的「显著」可能只是方差估错。</p><p>遗漏变量、反向因果仍按上一课的外生失败来读。本课的工具不洗偏误，只修覆盖率。</p><h3 id="稳健协方差不是稳健识别" tabindex="-1">稳健协方差不是稳健识别 <a class="header-anchor" href="#稳健协方差不是稳健识别" aria-label="Permalink to &quot;稳健协方差不是稳健识别&quot;">​</a></h3><p>「robust」在软件里几乎等于 White。它回答的是：给定外生，渐近方差怎么估。它不回答 \\(X\\) 是否外生。把 White 当成「所以因果更稳」，是把推断语言偷换成识别语言。GLS 若真知道 \\(\\Omega\\)，可以比 OLS 更有效；未知时乱加权，点估计自己也会歪。</p><p><span class="marginnote">Angrist–Pischke 的底线是：截面默认报异方差稳健 SE。这不是展示，是承认球形在应用里几乎从不成立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>White（1980）：用 \\(\\hat u_i^2 x_i x_i&#39;\\) 替换中间的 \\(\\sigma^2 X&#39;X\\)，得到对未知异方差一致的协方差。要求观测独立（或弱依赖到可以当独立），不要求知道 \\(\\mathrm{Var}(u_i\\mid x_i)\\) 的函数形式。时间序列上，独立失败：Newey–West 对 \\(\\hat u_t x_t\\) 的自协方差做 Bartlett 核加权，带宽 \\(L\\) 随 \\(T\\) 增大但慢于 \\(T\\)，得到 HAC——异方差且自相关一致。带宽太短，相关修不净；太长，有限样本方差膨胀，矩阵还可能接近奇异。</p>',11)),(a(),h(c,null,{default:i(()=>[E(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GM%5B%22%E7%90%83%E5%BD%A2%E8%AF%AF%E5%B7%AE%3A%20Gauss%E2%80%93Markov%22%5D%20--%3E%20OLS%5B%22OLS%20%E7%82%B9%E4%BC%B0%E8%AE%A1%E4%BB%8D%E5%8F%AF%E4%B8%80%E8%87%B4%22%5D%0A%20%20OLS%20--%3E%20DEF%5B%22%E9%BB%98%E8%AE%A4%20SE%20%E6%8C%89%20%CF%83%C2%B2I%22%5D%0A%20%20OLS%20--%3E%20W%5B%22White%3A%20%E6%88%AA%E9%9D%A2%E5%BC%82%E6%96%B9%E5%B7%AE%22%5D%0A%20%20OLS%20--%3E%20NW%5B%22Newey%E2%80%93West%3A%20%E5%8D%95%E5%BA%8F%E5%88%97%20HAC%22%5D%0A%20%20DEF%20--%3E%20WRONG%5B%22%E5%90%8D%E4%B9%89%E6%B0%B4%E5%B9%B3%E8%AF%B4%E8%B0%8E%22%5D%0A%20%20W%20--%3E%20INF%5B%22%E8%A6%86%E7%9B%96%E5%AF%B9%E5%87%86%E6%B8%90%E8%BF%91%E6%96%B9%E5%B7%AE%22%5D%0A%20%20NW%20--%3E%20INF%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>Wooldridge 的分工：截面用 White；单方程宏观用 HAC；面板组内相关不要拿 Newey–West 当默认——那是下一课的聚类。两者不要混成同一套软件开关。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把 \\(\\mathrm{Var}(X&#39;u/n)\\) 写成可估的外积和。White 让每个观测按自己的 \\(\\hat u_i^2\\) 贡献；等价于承认「不同 \\(x\\) 处噪声尺度不同」。HAC 在时域是截断自协方差，在频域是对谱密度在零频的核估计：短记忆下，远滞后被核压掉。核必须保证估计是半正定的——这正是 Newey–West 选 Bartlett 的理由。</p><p>有限样本里 \\(\\hat u_i\\) 比真 \\(u_i\\) 小（投影吃掉一部分），HC0 往往偏低；HC1–HC3 是杠杆修正。宏观 \\(T\\) 不大时，HAC 的名义 \\(t\\) 仍可乐观。这些是精度的下一阶，不改变本课的句子：先丢掉球形，再谈聚类。</p><p><span class="marginnote">GLS / FGLS 走另一条：先估 \\(\\Omega\\) 再变换。形式对则有效性高于 OLS+White；形式错则点估计与 SE 一起坏。应用默认常是 OLS 加稳健协方差，把效率让给稳健。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>White 不管同一家庭、同一企业重复出现：组内 \\(u\\) 相关时，它仍当独立加总，SE 系统性偏小。那一块交给<a href="/econ/clustered-se">聚类标准误</a>。空间相关、共同因子驱动的截面相关，HAC 也不覆盖。量化栏金融回归另有因子与 HAC 惯例，本课不搬那些表，以免吞并微观结构。</p><p>后课默认：写下 OLS 时，截面报 White，单序列报 HAC 并声明滞后；识别问题仍按外生来问。下一课把「独立观测」这条再拆掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>球形失败时 OLS 仍可一致，默认 SE 一般不一致。</li><li>White 修截面异方差；Newey–West 修单序列相关加异方差。</li><li>稳健协方差不修遗漏变量，只修覆盖。</li><li>组内相关不是 HAC 的对象，留给聚类。</li><li>出处：White, <em>Econometrica</em> 1980；Newey and West, <em>Econometrica</em> 1987；Wooldridge；Angrist and Pischke, <em>Mostly Harmless Econometrics</em>。</li></ul>',10))])}const W=o(d,[["render",m]]);export{S as __pageData,W as default};
